"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/hero-sections/variants/01-analytics-flow";
import View1 from "./components/hero-sections/variants/02-ai-teammates";
import View2 from "./components/hero-sections/variants/03-voice-mobile";
import View3 from "./components/hero-sections/variants/04-decision-spectrum";
import View4 from "./components/hero-sections/variants/05-defi-routing";
import View5 from "./components/hero-sections/variants/06-ai-marketplace";
import View6 from "./components/hero-sections/variants/07-signal-aurora";
import View7 from "./components/hero-sections/variants/12-split-demo";
const views={"analytics-flow":View0,"ai-teammates":View1,"voice-mobile":View2,"decision-spectrum":View3,"defi-routing":View4,"ai-marketplace":View5,"signal-aurora":View6,"split-demo":View7};
export interface ArtemisHeroSectionsProps {className?:string;variant?:"analytics-flow"|"ai-teammates"|"voice-mobile"|"decision-spectrum"|"defi-routing"|"ai-marketplace"|"signal-aurora"|"split-demo";}
export function ArtemisHeroSections({className,variant="analytics-flow"}:ArtemisHeroSectionsProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { Description, Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "../../../../lib/headless";
import { AnimatePresence, MotionConfig, motion, useReducedMotion } from "motion/react";
import { FileText, X } from "lucide-react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { reports, type ReportKey } from "./reports";
export function ReportBrief({ open, onClose, report }: {
    open: boolean;
    onClose: () => void;
    report: ReportKey;
}) {
    const reduce = useReducedMotion();
    const r = reports[report];
    const exit = reduce ? { duration: 0 } : { duration: 0.15, ease: ARTEMIS_EASE_OUT };
    return <AnimatePresence>{open ? (<Dialog static open onClose={onClose} className="art:relative art:z-[100]">
      <MotionConfig transition={exit}>
        <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-xl" initial={{ opacity: 0 }} animate={{ opacity: 1, transition: reduce ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT } }} exit={{ opacity: 0 }}/>
        <div className="art:fixed art:inset-4 art:z-[101] art:overflow-x-hidden art:overflow-y-auto"><div className="art:flex art:min-h-full art:items-center art:justify-center">
          <DialogPanel as={motion.div} className="art:max-h-[calc(100dvh-2rem)] art:w-full art:overflow-y-auto art:rounded-2xl art:border art:border-border art:bg-background art:text-foreground art:will-change-transform art:max-w-lg" initial={{ opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1, transition: reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL }} exit={{ opacity: 0, y: 6, scale: 0.96 }}>
            <div className="art:p-6 art:@min-[640px]/artemis:p-8">
              <div className="art:mb-6 art:flex art:items-center art:justify-between art:gap-3"><span className="art:flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground"><FileText className="art:size-4"/>Sample {report} brief</span><ArtemisButton variant="ghost" size="icon" className="art:size-9 art:rounded-full" aria-label="Close report brief" onClick={onClose}><X className="art:size-4"/></ArtemisButton></div>
              <DialogTitle className="art:text-xl art:font-medium">{r.title}</DialogTitle>
              <Description className="art:mt-3 art:text-sm art:leading-6 art:text-muted-foreground">{r.insight}</Description>
              <div className="art:mt-6 art:rounded-2xl art:border art:border-border art:p-4"><p className="art:text-xs art:text-muted-foreground">Total {r.unit} · Sample period</p><p className="art:mt-2 art:text-3xl art:font-medium art:tabular-nums">{r.total}</p><p className="art:mt-2 art:text-xs art:text-muted-foreground">{r.change}% above the previous sample period</p></div>
              <p className="art:mt-6 art:text-sm art:font-medium">Where to focus</p><p className="art:mt-2 art:text-sm art:leading-6 art:text-muted-foreground">{r.focus}</p>
              <div className="art:mt-7 art:flex art:justify-end"><ArtemisButton variant="tertiary" className="art:h-9 art:rounded-full" onClick={onClose}>Back to the report</ArtemisButton></div>
            </div>
          </DialogPanel>
        </div></div>
      </MotionConfig>
    </Dialog>) : null}</AnimatePresence>;
}

"use client";
// @zeus-internal
import { useId } from "react";
import { Area, CartesianGrid, ComposedChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { chartData, reports, type ReportKey } from "./reports";
const AXIS_TEXT_STYLE = {
  fill: "var(--artemis-muted-foreground)",
  fontSize: "var(--art-text-xs, 0.75rem)",
  fontFamily: "var(--artemis-font-sans, 'Artemis Sans', sans-serif)",
};
const axisNumber = (value: number) => value >= 1000 ? `${(value / 1000).toFixed(1)}k` : String(value);
export function ReportChart({ report }: {
    report: ReportKey;
}) {
    const id = `${useId()}-fill`;
    const data = chartData(report);
    const domain = reports[report].domain;
    return (<ResponsiveContainer width="100%" height="100%" minWidth={0}>
      <ComposedChart data={data} margin={{ top: 12, right: 8, bottom: 0, left: -16 }}>
        <defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="var(--artemis-primary)" stopOpacity={0.16}/><stop offset="1" stopColor="var(--artemis-primary)" stopOpacity={0}/></linearGradient></defs>
        <CartesianGrid vertical={false} stroke="var(--artemis-border)" strokeDasharray="3 5"/>
        <XAxis dataKey="date" axisLine={false} tickLine={false} tickMargin={12} minTickGap={42} tick={AXIS_TEXT_STYLE}/>
        <YAxis axisLine={false} tickLine={false} domain={[0, domain]} ticks={[0, domain / 3, domain * 2 / 3, domain]} tickFormatter={axisNumber} tick={AXIS_TEXT_STYLE}/>
        <Tooltip cursor={{ stroke: "var(--artemis-border)", strokeDasharray: "3 3" }} content={({ active, label, payload }) => active && payload?.length ? (<div className="art:rounded-xl art:border art:border-border art:bg-background art:px-3 art:py-2.5 art:text-xs art:text-foreground">
            <p className="art:mb-2 art:font-medium">{label}</p>
            {payload.map((entry, i) => <div key={i} className="art:mt-1.5 art:flex art:items-center art:justify-between art:gap-5"><span className="art:text-muted-foreground">{entry.name}</span><span className="art:font-medium art:tabular-nums">{report === "revenue" ? "$" : ""}{Number(entry.value).toLocaleString("en-US")}</span></div>)}
          </div>) : null}/>
        <Area type="monotone" dataKey="current" name="This period" stroke="var(--artemis-primary)" strokeWidth={2} fill={`url(#${id})`} fillOpacity={0.6} activeDot={{ r: 4, fill: "var(--artemis-primary)", stroke: "var(--artemis-background)", strokeWidth: 2 }} isAnimationActive={false}/>
        <Line type="monotone" dataKey="previous" name="Previous period" stroke="var(--artemis-muted-foreground)" strokeOpacity={0.55} strokeWidth={1.5} strokeDasharray="4 5" dot={false} activeDot={false} isAnimationActive={false}/>
      </ComposedChart>
    </ResponsiveContainer>);
}

// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
export function NumberTicker({ text, className }: {
    text: string;
    className: string;
}) { return <ArtemisRollingNumber text={text.startsWith("$")?text.slice(1):text} prefix={text.startsWith("$")?"$":""} className={className} duration={.6} stagger={.04}/>; }

// @zeus-internal
const series = {"reach": [[870, 950, 1040, 780, 1250, 1190, 1560, 1310, 1610, 1390, 1700, 1850, 1570, 1770], [710, 820, 890, 840, 980, 1040, 1120, 990, 1250, 1160, 1310, 1270, 1400, 1460]], "activation": [[42, 54, 51, 38, 63, 58, 78, 69, 85, 74, 92, 103, 86, 97], [38, 42, 46, 40, 51, 47, 58, 55, 67, 62, 71, 75, 73, 80]], "revenue": [[1260, 1380, 1140, 1080, 1560, 1440, 1980, 1740, 2160, 1860, 2400, 2760, 2220, 2580], [1020, 1140, 1080, 960, 1260, 1320, 1500, 1440, 1680, 1560, 1800, 1920, 1860, 2040]]};
export type ReportKey = keyof typeof series;
export const reports = {
    reach: {
        label: "Reach", unit: "sessions", total: "18,840", change: "23.6",
        stats: [["Engaged sessions", "13,753"], ["Returning visitors", "4,145"]],
        title: "A steady stream of new visitors", shareTitle: "Where they found you", shareUnit: "sessions",
        shares: [["Search", 40], ["Community", 25], ["Email", 20], ["Bookmarks", 15]],
        insight: "Search brings the largest share of visits. The latest content update is worth a closer look.",
        focus: "Compare the pages people discover through search with the pages that bring them back.",
        domain: 1950,
    },
    activation: {
        label: "Activation", unit: "new accounts", total: "990", change: "23.0",
        stats: [["First projects created", "673"], ["Teammates invited", "412"]],
        title: "Small actions, lasting momentum", shareTitle: "Their first useful action", shareUnit: "first actions",
        shares: [["Created a project", 45], ["Invited a teammate", 27], ["Connected a source", 18], ["Saved a view", 10]],
        insight: "Project creation is the most common first step. Team invitations follow soon after.",
        focus: "Make the path from a new account to its first project shorter, then compare the next cohort.",
        domain: 105,
    },
    revenue: {
        label: "Revenue", unit: "sales", total: "$25,560", change: "24.2",
        stats: [["Paid orders", "426"], ["Average order", "$60"]],
        title: "The visits that turn into value", shareTitle: "What brought the order", shareUnit: "attributed sales",
        shares: [["Product guides", 38], ["Weekly digest", 29], ["Partner stories", 21], ["Direct visits", 12]],
        insight: "Product guides lead attributed sales. The weekly digest contributes nearly a third of orders.",
        focus: "Review the guide-to-order path and carry its clearest examples into the next digest.",
        domain: 2850,
    },
} as const;
export const reportKeys: ReportKey[] = ["reach", "activation", "revenue"];
export function chartData(key: ReportKey) {
    return series[key][0].map((current, i) => ({
        date: i < 5 ? `Sep ${26 + i}` : `Oct ${i - 4}`,
        current, previous: series[key][1][i],
    }));
}

"use client";
// @zeus-internal
import { artemisWordMotion } from "../../../lib/word-motion";
import { motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";
import { ArrowDown, Check, CheckCheck, Pause, Play } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { Avatar, type TeammateKey } from "./02-ai-teammates/avatar";
import { team, teamKeys } from "./02-ai-teammates/data";
import { TeamShader } from "./02-ai-teammates/shader";
import { WorkPreview } from "./02-ai-teammates/work-preview";
import { TeamBrief } from "./02-ai-teammates/brief";
export default function HeroSectionsAiTeammates() {
    const reduce = useReducedMotion();
    const id = useId();
    const [selected, setSelected] = useState<TeammateKey>("memberA");
    const [elapsed, setElapsed] = useState(0);
    const [playing, setPlaying] = useState(true);
    const [run, setRun] = useState(0);
    const [query, setQuery] = useState("");
    const [searchFocused, setSearchFocused] = useState(false);
    const [taskFocused, setTaskFocused] = useState(false);
    const [briefOpen, setBriefOpen] = useState(false);
    const [showLatest, setShowLatest] = useState(false);
    const appRef = useRef<HTMLDivElement>(null);
    const conversationRef = useRef<HTMLElement>(null);
    const conversationInView = useInView(conversationRef, { amount: 0.5 });
    const visualRef = useRef<HTMLDivElement>(null);
    const visualInView = useInView(visualRef, { amount: 0.1 });
    const person = team[selected];
    const phase = elapsed < 1800 ? 0 : elapsed < 3600 ? 1 : elapsed < 5800 ? 2 : 3;
    const complete = phase === 3;
    const status = complete ? "Ready for review" : playing ? "Working on it" : "Paused";
    const filtered = teamKeys.filter(key => `${team[key].name} ${team[key].role} ${team[key].idle}`.toLowerCase().includes(query.trim().toLowerCase()));
    useEffect(() => { if (!playing || complete || !conversationInView)
        return; const timer = window.setTimeout(() => setElapsed([1800, 3600, 5800][phase]), [1800, 1800, 2200][phase]); return () => window.clearTimeout(timer); }, [playing, complete, phase, run, conversationInView]);
    useEffect(() => { if (complete)
        setPlaying(false); }, [complete]);
    useEffect(() => { if (reduce) {
        setElapsed(5800);
        setPlaying(false);
    } }, [reduce]);
    useEffect(() => { const node = conversationRef.current; if (node)
        node.scrollTop = node.scrollHeight; }, [phase, run]);
    const replay = () => { setElapsed(reduce ? 5800 : 0); setPlaying(!reduce); setRun(n => n + 1); };
    const choose = (key: TeammateKey) => { setSelected(key); replay(); };
    const rise = (delay: number) => ({ initial: reduce ? false as const : { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: reduce ? { duration: 0 } : { duration: 0.5, delay, ease: ARTEMIS_EASE_OUT } });
    const word = (index: number) => artemisWordMotion(index, reduce === true, { stagger: 0, delay: [0, .055, .12, .175][index] ?? 0, blur: 4, yOffset: 12 });
    return (<>
      <section aria-labelledby={`${id}-title`} className="art:relative art:isolate art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-6xl">
          <div className="art:grid art:items-center art:gap-6 art:@min-[1024px]/artemis:grid-cols-[0.95fr_1.05fr] art:@min-[1024px]/artemis:gap-12">
            <div className="art:relative art:z-10 art:pt-4 art:text-center art:@min-[1024px]/artemis:py-10 art:@min-[1024px]/artemis:text-left">
              <motion.p className="art:inline-flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground" {...rise(0)}>
                <span className="art:grid art:size-7 art:place-items-center art:rounded-full art:border art:border-border">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-message-circle art:size-3.5" aria-hidden="true">
                    <path d="M2.992 16.342a2 2 0 0 1 .094 1.167l-1.065 3.29a1 1 0 0 0 1.236 1.168l3.413-.998a2 2 0 0 1 1.099.092 10 10 0 1 0-4.777-4.719"/>
                  </svg>
                </span>
                {"A few extra minds on your team"}
              </motion.p>
              <h1 id={`${id}-title`} className="art:text-balance art:font-sans art:font-medium art:text-5xl art:@min-[768px]/artemis:text-6xl art:leading-[0.94] art:tracking-[-0.055em] art:mt-6">
                <span className="art:block">
                  <span className="art:block">
                    <motion.span className="art:inline-block art:will-change-transform" {...word(0)}>
                      {"Your"}
                      <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                        {"\u00A0"}
                      </span>
                    </motion.span>
                    <motion.span className="art:inline-block art:will-change-transform" {...word(1)}>
                      {"new"}
                    </motion.span>
                  </span>
                </span>
                <span className="art:mt-2 art:block">
                  <span className="art:block">
                    <motion.span className="art:inline-block art:will-change-transform" {...word(2)}>
                      {"AI"}
                      <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                        {"\u00A0"}
                      </span>
                    </motion.span>
                    <motion.span className="art:inline-block art:will-change-transform" {...word(3)}>
                      {"teammates"}
                    </motion.span>
                  </span>
                </span>
              </h1>
              <motion.p className="art:mx-auto art:mt-6 art:max-w-md art:text-pretty art:text-sm art:leading-7 art:text-muted-foreground art:@min-[640px]/artemis:text-base art:@min-[1024px]/artemis:mx-0" {...rise(0.12)}>
                {"Give each teammate a role, share what needs doing, and let them take it from there. They bring the finished work back to you."}
              </motion.p>
              <motion.div className="art:mt-7 art:flex art:flex-wrap art:items-center art:justify-center art:gap-3 art:@min-[1024px]/artemis:justify-start" {...rise(0.18)}>
                <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => { replay(); appRef.current?.scrollIntoView({ behavior: reduce ? "instant" : "smooth", block: "center" }); }} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:relative art:after:absolute art:after:-inset-y-0.5 art:after:inset-x-0 art:rounded-full" tabIndex={0}>
                  {"Meet your team"}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down art:size-4" aria-hidden="true">
                    <path d="M12 5v14"/>
                    <path d="m19 12-7 7-7-7"/>
                  </svg>
                </motion.button>
                <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setBriefOpen(true)} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:relative art:after:absolute art:after:-inset-y-0.5 art:after:inset-x-0 art:rounded-full" tabIndex={0}>
                  {"See their work"}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                    <path d="M7 7h10v10"/>
                    <path d="M7 17 17 7"/>
                  </svg>
                </motion.button>
              </motion.div>
              <motion.p className="art:mt-6 art:text-xs art:text-muted-foreground" {...rise(0.24)}>
                {"A little more headspace. A lot more possibility."}
              </motion.p>
            </div>
            <div ref={visualRef} className="art:relative art:isolate art:min-w-0">
              <div aria-hidden="true" className="art:pointer-events-none art:absolute art:-inset-x-8 art:-inset-y-4 art:-z-10 art:[mask-image:radial-gradient(ellipse_at_center,black_25%,transparent_70%)] art:@min-[640px]/artemis:-inset-x-12 art:@min-[640px]/artemis:-inset-y-8">
                <TeamShader active={visualInView}/>
              </div>
              <div className="art:absolute art:inset-x-3 art:top-5 art:z-10 art:flex art:items-center art:@min-[640px]/artemis:inset-x-6">
                <p className="art:flex art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background/90 art:px-3 art:py-2 art:text-xs">
                  <Avatar kind="assistant" className="art:shrink-0 art:size-5"/>
                  {"Assistant"}
                  {" \u00B7 Your AI team"}
                </p>
              </div>
              <svg aria-hidden="true" viewBox="0 0 600 420" fill="none" className="art:pointer-events-none art:absolute art:inset-0 art:size-full art:text-foreground/10">
                <ellipse cx="300" cy="235" rx="250" ry="107" stroke="currentColor" strokeDasharray="2 7" transform="rotate(-12 300 235)"/>
                <ellipse cx="300" cy="235" rx="220" ry="76" stroke="currentColor" transform="rotate(12 300 235)"/>
              </svg>
              <nav aria-label="AI teammates" className="art:relative art:grid art:min-h-96 art:grid-cols-3 art:items-center art:gap-1 art:px-1 art:pt-20 art:pb-16 art:@min-[640px]/artemis:gap-3 art:@min-[640px]/artemis:px-4 art:@min-[1024px]/artemis:min-h-[28rem]">
        {teamKeys.map((key, i) => <motion.div key={key} initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: reduce ? 0 : i === 1 ? -28 : 16 }} transition={{ duration: 0.6, delay: i * 0.08, ease: ARTEMIS_EASE_OUT }}>
        <motion.button type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:block art:w-full art:text-center art:rounded-full" aria-label={`Meet ${team[key].name}, ${team[key].role}`} aria-pressed={selected === key} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => choose(key)}>
        <motion.span className="art:flex art:flex-col art:items-center" initial={{ scale: 1 }} animate={{ scale: reduce ? 1 : selected === key ? 1.04 : 0.94 }} transition={{ duration: 0.35, ease: ARTEMIS_EASE_OUT }}>
        <Avatar blink kind={key} className="art:shrink-0 art:size-24 art:@min-[640px]/artemis:size-32 art:@min-[1024px]/artemis:size-36"/>
        <span className={`art:mt-2 art:inline-flex art:items-center art:gap-1.5 art:rounded-full art:border art:bg-background/90 art:px-3 art:py-1.5 art:text-sm art:font-medium ${selected === key ? "art:border-foreground/30" : "art:border-border"}`}>{team[key].name}{selected === key ? <ArrowDown className="art:size-3"/> : null}</span>
        <span className="art:mt-2 art:text-xs art:text-muted-foreground">{team[key].role}</span>
        </motion.span></motion.button></motion.div>)}
    </nav>
              <p className="art:absolute art:inset-x-0 art:bottom-5 art:text-center art:text-xs art:text-muted-foreground">
                {"Pick a personality. Put a great mind to work."}
              </p>
            </div>
          </div>
          <motion.div ref={appRef} className="art:relative art:z-10 art:mt-8 art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:@min-[1024px]/artemis:mt-4" {...rise(0.24)} animate={reduce ? { opacity: 1, y: 0 } : undefined} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>
            <div className="art:flex art:min-w-0 art:flex-col art:@min-[768px]/artemis:flex-row">
              <aside className="art:border-border art:border-b art:@min-[768px]/artemis:flex art:@min-[768px]/artemis:w-56 art:@min-[768px]/artemis:shrink-0 art:@min-[768px]/artemis:flex-col art:@min-[768px]/artemis:border-r art:@min-[768px]/artemis:border-b-0 art:@min-[1024px]/artemis:w-64">
